"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["73473"],{7279(e){e.exports=JSON.parse('{"id":"FIN-088","slug":"loan-term","term":"Loan Term","also_known_as":[],"difficulty":"Beginner","definition":"The loan term is the length of time over which a loan must be repaid, such as three years for a car loan or 25 years for a mortgage.","explanation":["The loan term is one of the key features of any loan, alongside the amount borrowed and the interest rate. It decides how many payments you make and strongly affects both the monthly payment and the total cost.","A longer term spreads repayments over more months, so each payment is smaller. But interest is charged for longer, so the total cost rises. For a 10,000 loan at 8%, a three-year term costs about 313 a month and about 1,280 in total interest. A five-year term lowers the payment to about 203, but total interest rises to about 2,170.","A shorter term means higher payments but less interest overall, and the debt is cleared sooner.","Choosing a term involves balancing affordability now against total cost. Some loans allow extra payments without penalty, which lets borrowers choose a longer term for safety but repay faster when they can. For assets that lose value, such as cars, a loan term longer than the asset\'s useful life can leave the borrower owing more than the asset is worth."],"note":"","total":1725,"prev":{"slug":"loan-origination","term":"Loan Origination"},"next":{"slug":"loan-to-cost-ratio","term":"Loan-to-Cost Ratio"}}')}}]);